steps.text:
/*
	VIOC_air_assault.sqf - parche air_assault de VIOC (2026-10-17). No es del autor de la mision.
	Lo carga init.sqf SOLO en el servidor (en la partida LAN el anfitrion es el servidor: la consola LOCAL EXEC llega aqui).

	ASALTO AEREO DE LA IA CON TROPAS REGULARES (no es una operacion especial):
	- Cada VIOC_AIR_ASSAULT minutos (lobby: 0 = no, 10, 15 por defecto, 20) el bando del jugador (y, con
	  VIOC_AIR_ASSAULT_ENEMY = 1, tambien el enemigo) lanza UN asalto aereo si no tiene otro en curso:
	    * un Black Hawk (UH-60) con 8 soldados regulares sale de su fabrica aerea o de un aerodromo propio (aparece en el
	      aire 1 km detras del punto de salida), vuela bajo hasta una zona de aterrizaje a 400-600 m de un pueblo enemigo o
	      neutral del frente, aterriza, los soldados bajan y atacan el pueblo (MOVE + SAD + MOVE al centro, en bucle) y el
	      helicoptero vuelve por donde vino y se borra cuando ningun jugador esta cerca;
	    * a veces (VIOC_AIR_ASSAULT_HEAVY, 30 %) un Chinook (CH-47F) con 14-16 soldados en vez del Black Hawk;
	    * a veces (VIOC_AIR_ASSAULT_ESCORT, 50 %) una escolta: AH-64D de EE. UU. o Arpia IV de Colombia (mision B), AH-64D
	      (mision A), Mi-24/Ka-52 (Rusia), que da vueltas sobre la zona de aterrizaje (punto de ruta LOITER, 350 m) unos
	      5 min (hasta 3 min despues del aterrizaje, 10 min como mucho), ataca lo que ve y vuelve.
	- Helicopteros: de la lista de la fabrica aerea del bando (CTI_<BANDO>_AirUnits, la de la faccion de la mision) y de
	  su nivel aereo, con la tabla VIOC_AA_TABLE (clase que se crea + clases de la lista que la habilitan; selva o
	  desierto segun CTI_CAMO_ACTIVATION). Nivel necesario = el de compra de la clase, como mucho VIOC_AA_LEVEL_CAP (2,
	  el nivel medio); en un bando de Colombia las clases de EE. UU. (apoyo) piden siempre ese nivel medio.
	  Sin fila valida en la tabla, el helicoptero mas barato de la lista con asientos suficientes.
	- Infanteria: listas de pueblo del bando (<BANDO>_INFANTRY_SQ_LIGHT/_MG/_AT), creada con CTI_CO_FNC_CreateUnit
	  (equipo de ai_loadouts, ropa de tropical_gear o nation_narco, habilidad de la mision): jefe + 1 ametrallador + 1
	  antitanque (2 y 2 en el Chinook) + fusileros.
	- Condiciones: el bando tiene una fabrica aerea viva (BECTI no tiene helipuerto como estructura) o un aerodromo
	  propio (pueblo del bando a menos de 1500 m del punto ILS de un aeropuerto de CfgWorlds) sin enemigos a 500 m; el
	  objetivo esta a mas de 1500 m (y menos de 12 km) de ese punto; zona de aterrizaje plana, en tierra, despejada, sin
	  antiaereas enemigas (misiles o canones) a 1000 m, sin blindados enemigos a 800 m, con menos de 3 enemigos a 300 m,
	  a mas de 800 m de bases enemigas y en la misma tierra que el pueblo (sin 20 m de agua seguida en linea recta hasta el
	  centro); nunca dos asaltos a la vez por bando; como mucho 24 hombres vivos de asaltos por bando contando el nuevo;
	  presupuesto de IA de perf_cleanup con 30 plazas de margen.
	- Objetivo: uno de los 5 pueblos no propios mas cercanos a lo propio (el frente, como specops); pesan el triple los
	  que el bando quiere recuperar (pedidos de contraataque de ai_tactics, VIOC_TAC_REQ) y el doble los que ya atacan sus
	  escuadras IA (cti_order_pos); no se repite un pueblo en 15 min; no se eligen los de una operacion especial del bando.
	- Coste: soldados (precio de compra de cada clase) + 15 % del precio de compra de cada helicoptero por vuelo. Lo paga el
	  comandante IA con sus fondos (conserva 5000); si el comandante es un jugador humano no se toca su dinero: paga el
	  equipo IA mas rico del bando (conserva 500), como las operaciones especiales. Si no alcanza: sin escolta, despues
	  Black Hawk en vez de Chinook, y si tampoco alcanza no sale. Si el asalto se cancela antes de aterrizar, se devuelve.
	- AA enemiga: si derriban el helicoptero mueren los que van dentro (no hay devolucion).
	- Aviso solo al bando propio: "[Asalto aereo] Asalto aereo hacia X ...", el desembarco y si lo derriban.
	- Fin: pueblo tomado + 5 min, 25 min de asalto o 1 hombre o menos; despues se quedan en el pueblo (si lo tomaron) o se
	  retiran hacia su zona de aterrizaje, y se borran cuando ningun jugador esta a 1000 m. Helicopteros y pilotos se
	  borran al volver (sin jugadores a 1500 m). Los helicopteros llevan vioc_aa = true: no se guardan en la partida
	  (gancho en Server_SaveToProfile.sqf). Las escuadras no son equipos de BECTI: ai_tactics y ai_transport no las tocan
	  (ai_tactics solo maneja grupos de cti_teams; caminan los 400-600 m desde la zona de aterrizaje).
	- Codigo reutilizado (copiado, con prefijo VIOC_AA_, para no depender de que specops o ai_tactics esten activos):
	  VIOC_specops.sqf (soHumanSides, soPlayersNear, soBase, soEnemyBases, soIsLand, soClamp, soPickIdx, soPayer, soCharge,
	  la busqueda de zona de aterrizaje de soFindLZ y el vuelo/aterrizaje/desembarco de soDoHeli), VIOC_ai_tactics.sqf
	  (clearWp, assaultWp, la eleccion de pueblos de soPickTarget/forceCA), VIOC_air_support_server.sqf (createVehicleCrew
	  y paso de la tripulacion a un grupo del bando), VIOC_irregular.sqf (IW_fnc_room / IW_fnc_reserve del presupuesto).

	Consola (LOCAL EXEC en el anfitrion):
	  hint (call VIOC_AA_fnc_info);                        estado (tambien al portapapeles y al registro)
	  hint ([west] call VIOC_AA_fnc_force);                asalto YA del Oeste, gratis (sin esperar el intervalo)
	  hint ([west, true, "ch", 1] call VIOC_AA_fnc_force); ... con Chinook ("ch") o Black Hawk ("bh") y escolta (1) o sin (0)
	  hint ([west, false] call VIOC_AA_fnc_force);         ... pagando como la IA
	  VIOC_AA_DEBUG = true;                                cada paso en systemChat del anfitrion
	  VIOC_AA_INFO = [lanzados, desembarcos, derribados, pueblos tomados, cancelados, escoltas, Chinook]
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_AA_LOADED") exitWith {};
VIOC_AA_LOADED = true;

//--- Ajustes
VIOC_AA_PERIOD = 30;              // s por pasada del gestor
VIOC_AA_RETRY = 180;              // s: si no se pudo lanzar, se reintenta a los 3 min
VIOC_AA_MIN_DIST = 1500;          // m: el objetivo esta a mas de esto del punto de salida
VIOC_AA_MAX_DIST = 12000;         // m: y a menos de esto
VIOC_AA_FRONT = 1500;             // m: pueblos del frente: hasta esto mas lejos de lo propio que el no propio mas cercano
VIOC_AA_FRONT_MAX = 6000;         // m: nunca mas lejos de lo propio que esto
VIOC_AA_LZ_R = [400, 600];        // m del centro del pueblo a la zona de aterrizaje
VIOC_AA_AA_R = 1000;              // m: sin antiaereas enemigas a esta distancia de la zona de aterrizaje
VIOC_AA_GUN_HIT = 56;             // "hit" minimo de una bala para contar como canon antiaereo (ZU-23 60-84; 12,7 mm 25-55)
VIOC_AA_TANK_R = 800;             // m: sin blindados enemigos tripulados
VIOC_AA_INF_R = 300;              // m: enemigos alrededor de la zona de aterrizaje...
VIOC_AA_INF_MAX = 3;              // ...menos de esto
VIOC_AA_BASE_R = 800;             // m: lejos de las bases enemigas
VIOC_AA_SAFE_ORIGIN = 500;        // m: punto de salida sin enemigos (3 o mas = disputado)
VIOC_AA_SPAWN_BACK = 1000;        // m detras del punto de salida donde aparecen (y se borran) los helicopteros
VIOC_AA_ALT = 90;                 // m de altura del transporte
VIOC_AA_ESC_ALT = 120;            // m de altura de la escolta
VIOC_AA_N_BH = 8;                 // soldados en el Black Hawk
VIOC_AA_N_CH = [14, 16];          // soldados en el Chinook
VIOC_AA_CREW_BH = 4;              // tripulacion estimada (presupuesto de IA): transporte, Chinook, escolta
VIOC_AA_CREW_CH = 5;
VIOC_AA_CREW_ESC = 2;
VIOC_AA_LOITER = 300;             // s de vueltas de la escolta sobre la zona (y hasta 3 min despues del aterrizaje)
VIOC_AA_LOITER_MAX = 600;         // s como mucho
VIOC_AA_LOITER_R = 350;           // m de radio de las vueltas
VIOC_AA_HOLD = 300;               // s en el pueblo tomado antes de terminar
VIOC_AA_LIFETIME = 1500;          // s de asalto como maximo (25 min)
VIOC_AA_FREE_R = 1000;            // m: la infanteria se borra sin jugadores a esta distancia
VIOC_AA_AIR_FREE_R = 1500;        // m: los helicopteros se borran sin jugadores a esta distancia
VIOC_AA_RESERVE = 5000;           // el comandante IA nunca baja de esto por un asalto
VIOC_AA_RESERVE_TEAM = 500;       // idem para el equipo IA que paga cuando el comandante es humano
VIOC_AA_FLIGHT = 0.15;            // parte del precio de compra de cada helicoptero que se cobra por vuelo
VIOC_AA_UNIT_DEF = 500;           // precio de un soldado si su clase no tiene precio en la mision
VIOC_AA_HELI_DEF = 24000;         // idem para un helicoptero
VIOC_AA_LEVEL_CAP = 2;            // nivel aereo "medio": con el, cualquier helicoptero de la lista sirve
VIOC_AA_SIDE_CAP = 24;            // hombres vivos de asaltos aereos por bando (tambien los que esperan para borrarse)
VIOC_AA_AI_MARGIN = 30;           // plazas libres que siempre quedan en el presupuesto de IA (revision: como capital_reinforce)
VIOC_AA_TOWN_CD = 900;            // s: el mismo bando no vuelve a elegir ese pueblo
VIOC_AA_TOWN_CD_FAIL = 600;       // s: pueblo sin zona de aterrizaje segura
if (isNil "VIOC_AA_DEBUG") then {VIOC_AA_DEBUG = false};

//--- Parametros de lobby (en "Un jugador" valen los de por defecto)
VIOC_AA_EVERY = missionNamespace getVariable ["VIOC_AIR_ASSAULT", 15];
if !(VIOC_AA_EVERY isEqualType 0) then {VIOC_AA_EVERY = 15};
VIOC_AA_P_ESC = missionNamespace getVariable ["VIOC_AIR_ASSAULT_ESCORT", 50];
if !(VIOC_AA_P_ESC isEqualType 0) then {VIOC_AA_P_ESC = 50};
VIOC_AA_P_HEAVY = missionNamespace getVariable ["VIOC_AIR_ASSAULT_HEAVY", 30];
if !(VIOC_AA_P_HEAVY isEqualType 0) then {VIOC_AA_P_HEAVY = 30};
VIOC_AA_ENEMY = missionNamespace getVariable ["VIOC_AIR_ASSAULT_ENEMY", 0];
if !(VIOC_AA_ENEMY isEqualType 0) then {VIOC_AA_ENEMY = 0};

//--- Estado (servidor)
VIOC_AA_OPS = [];                 // asaltos (hashmaps), en curso y en limpieza (los ultimos 8 terminados quedan para la consola)
VIOC_AA_ACTIVE = [false, false];  // [oeste, este]: asalto en curso
VIOC_AA_NEXT = [1e9, 1e9];        // momento desde el que puede salir el proximo
VIOC_AA_LAST = ["", ""];
VIOC_AA_INFO = [0, 0, 0, 0, 0, 0, 0];
VIOC_AA_HUMANS = [];
VIOC_AA_AIRF = [];                // [punto ILS, pueblo duenio] de cada aeropuerto de CfgWorlds
VIOC_AA_AACACHE = createHashMap;  // clase -> antiaerea si/no
VIOC_AA_HM = createHashMap;       // solo para isEqualType
VIOC_AA_ID = 0;
VIOC_AA_READY = false;

//--- [rol, nacion, mod, clase (selva/bosque), clase (desierto, "" = la misma), clases de la lista de la fabrica aerea que la habilitan]
//--- Roles: "bh" transporte de 8, "ch" Chinook de 14-16, "esc" escolta. Naciones: COL (mision B), US, RU, INS (narco/ChDKZ).
//--- Todas comprobadas en la configuracion de la linea 12 (CUP, RHS, @col) con work/v6_build/air_assault/classes_verified.txt;
//--- en el juego se vuelven a comprobar con isClass, scope, bando e isKindOf "Helicopter".
VIOC_AA_TABLE = [
	["bh", "COL", "RHS", "EJC_ejc_rhs_uh60l", "", ["EJC_ejc_rhs_uh60l"]],
	["bh", "COL", "RHS", "UH60_colombiaFAC", "", ["UH60_colombiaFAC"]],
	["bh", "COL", "RHS", "UH60P_colombiaFAC", "", ["UH60P_colombiaFAC"]],
	["bh", "US", "RHS", "RHS_UH60M", "RHS_UH60M_d", ["RHS_UH60M", "RHS_UH60M_d", "RHS_UH60M2", "RHS_UH60M2_d", "RHS_UH60M_ESSS", "RHS_UH60M_ESSS_d"]],
	["bh", "US", "CUP", "CUP_B_UH60M_US", "", ["CUP_B_UH60M_US", "CUP_B_UH60M_FFV_US", "CUP_B_UH60M_Unarmed_US", "CUP_B_UH60M_Unarmed_FFV_US"]],
	["bh", "RU", "RHS", "RHS_Mi8AMT_vvs", "", ["RHS_Mi8AMT_vvs", "RHS_Mi8mt_vvs", "RHS_Mi8MTV3_vvs", "RHS_Mi8AMTSh_vvs"]],
	["bh", "RU", "CUP", "CUP_O_Mi8AMT_RU", "", ["CUP_O_Mi8AMT_RU", "CUP_O_Mi8_RU"]],
	["bh", "INS", "RHS", "rhsgref_ins_Mi8amt", "", ["rhsgref_ins_Mi8amt"]],
	["ch", "US", "RHS", "RHS_CH_47F", "RHS_CH_47F_10", ["RHS_CH_47F", "RHS_CH_47F_10", "RHS_CH_47F_light"]],
	["ch", "US", "CUP", "CUP_B_CH47F_USA", "", ["CUP_B_CH47F_USA"]],
	["esc", "COL", "RHS", "col_ArpyIV", "", ["col_ArpyIV"]],
	["esc", "COL", "RHS", "UH60AFAC_colombia", "", ["UH60AFAC_colombia"]],
	["esc", "US", "RHS", "RHS_AH64D", "", ["RHS_AH64D", "RHS_AH64D_wd"]],
	["esc", "US", "CUP", "CUP_B_AH64D_DL_USA", "", ["CUP_B_AH64D_DL_USA", "CUP_B_AH64_DL_USA"]],
	["esc", "RU", "RHS", "RHS_Ka52_vvs", "", ["RHS_Ka52_vvs"]],
	["esc", "RU", "RHS", "RHS_Mi24P_vvs", "", ["RHS_Mi24P_vvs", "RHS_Mi24V_vvs", "RHS_Mi24Vt_vvs"]],
	["esc", "RU", "CUP", "CUP_O_Ka52_RU", "", ["CUP_O_Ka52_RU"]],
	["esc", "RU", "CUP", "CUP_O_Mi24_V_Dynamic_RU", "", ["CUP_O_Mi24_V_Dynamic_RU", "CUP_O_Mi24_P_Dynamic_RU"]]
];

//=====================================================================================================================
// Utilidades
//=====================================================================================================================
VIOC_AA_fnc_log = {
	params ["_m"];
	diag_log format ["[VIOC air_assault] %1", _m];
	if (VIOC_AA_DEBUG && {hasInterface}) then {systemChat format ["[AA] %1", _m]};
};

//--- [bando, texto]: aviso a los jugadores de ese bando
VIOC_AA_fnc_say = {
	params ["_side", "_txt"];
	[_txt] remoteExec ["systemChat", _side];
	[format ["(%1) %2", _side, _txt]] call VIOC_AA_fnc_log;
};

VIOC_AA_fnc_stat = {
	params ["_k"];
	VIOC_AA_INFO set [_k, (VIOC_AA_INFO select _k) + 1];
};

VIOC_AA_fnc_idx = {
	params ["_side"];
	[0, 1] select (_side isEqualTo east)
};

VIOC_AA_fnc_name = {
	params ["_c"];
	getText (configFile >> "CfgVehicles" >> _c >> "displayName")
};

//--- (de VIOC_specops.sqf, soHumanSides) bandos (oeste/este) que tuvieron algun jugador humano
VIOC_AA_fnc_humans = {
	private _pl = allPlayers - (entities "HeadlessClient_F");
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
	{
		private _s = side group _x;
		if (_s in [west, east]) then {VIOC_AA_HUMANS pushBackUnique _s};
	} forEach _pl;
	VIOC_AA_HUMANS
};

//--- bandos del jugador (sin jugadores todavia: el Oeste, el habitual)
VIOC_AA_fnc_playerSides = {
	private _h = call VIOC_AA_fnc_humans;
	if (count _h == 0) then {[west]} else {+_h}
};

//--- [bando] -> true si ese bando hace asaltos aereos automaticos
VIOC_AA_fnc_sideOn = {
	params ["_side"];
	(VIOC_AA_EVERY > 0) && {(_side in (call VIOC_AA_fnc_playerSides)) || {VIOC_AA_ENEMY > 0}}
};

//--- (de VIOC_specops.sqf, soPlayersNear) true si hay algun jugador a menos de _dist de alguno de los objetos o posiciones
VIOC_AA_fnc_playersNear = {
	params ["_objs", "_dist"];
	private _pl = allPlayers select {alive _x && {!(_x isKindOf "HeadlessClient_F")}};
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
	private _near = false;
	{
		private _o = _x;
		if (({(_x distance2D _o) < _dist} count _pl) > 0) exitWith {_near = true};
	} forEach _objs;
	_near
};

//--- (de VIOC_specops.sqf) en tierra (y sin agua a _r m en cruz)
VIOC_AA_fnc_isLand = {
	params ["_p", ["_r", 0]];
	if (surfaceIsWater _p) exitWith {false};
	if (_r <= 0) exitWith {true};
	({surfaceIsWater (_p getPos [_r, _x])} count [0, 90, 180, 270]) == 0
};

//--- (revision A2) [desde, hasta] -> true si la linea recta no tiene 20 m o mas de agua seguida (muestra cada 10 m; los
//--- caminos y puentes cuentan como tierra): la zona de aterrizaje esta en la misma masa de tierra que el pueblo
VIOC_AA_fnc_dry = {
	params ["_a", "_b"];
	private _n = ceil ((_a distance2D _b) / 10);
	private _run = 0;
	private _ok = true;
	for "_i" from 1 to (_n - 1) do {
		_run = if (surfaceIsWater [(_a select 0) + ((_b select 0) - (_a select 0)) * _i / _n, (_a select 1) + ((_b select 1) - (_a select 1)) * _i / _n]) then {_run + 10} else {0};
		if (_run >= 20) exitWith {_ok = false};
	};
	_ok
};

VIOC_AA_fnc_clamp = {
	params ["_p"];
	[((_p select 0) max -1000) min (worldSize + 1000), ((_p select 1) max -1000) min (worldSize + 1000), 0]
};

//--- (de VIOC_specops.sqf, soPickIdx) indice al azar con pesos
VIOC_AA_fnc_pickIdx = {
	params ["_weights"];
	private _tot = 0;
	{_tot = _tot + _x} forEach _weights;
	private _r = random _tot;
	private _i = (count _weights) - 1;
	{
		_r = _r - _x;
		if (_r <= 0) exitWith {_i = _forEachIndex};
	} forEach _weights;
	_i
};

//--- (de VIOC_ai_tactics.sqf) borra todos los puntos de ruta del grupo
VIOC_AA_fnc_clearWp = {
	params ["_g"];
	for "_i" from ((count (waypoints _g)) - 1) to 0 step -1 do {deleteWaypoint [_g, _i]};
};

//--- (de VIOC_specops.sqf, soBase) base del bando: HQ (aunque este destruido), primera estructura o marcador de reaparicion
VIOC_AA_fnc_base = {
	params ["_side"];
	private _logic = _side call CTI_CO_FNC_GetSideLogic;
	if (isNil "_logic" || {!(_logic isEqualType objNull)} || {isNull _logic}) exitWith {[]};
	private _hq = _logic getVariable ["cti_hq", objNull];
	if (_hq isEqualType objNull && {!isNull _hq}) exitWith {getPosATL _hq};
	private _st = _logic getVariable ["cti_structures", []];
	if (_st isEqualType [] && {count _st > 0} && {(_st select 0) isEqualType objNull} && {!isNull (_st select 0)}) exitWith {getPosATL (_st select 0)};
	private _m = format ["CTI_%1Respawn", _side];
	if (markerType _m != "") exitWith {markerPos _m};
	[]
};

VIOC_AA_fnc_enemyBases = {
	params ["_side"];
	private _res = [];
	{
		if !(_x isEqualTo _side) then {
			private _b = [_x] call VIOC_AA_fnc_base;
			if (count _b > 1) then {_res pushBack _b};
		};
	} forEach [west, east];
	_res
};

//--- [posicion, bando, radio] -> enemigos vivos (hombres, vehiculos y estaticas de los otros bandos) a ese radio
VIOC_AA_fnc_enemyCount = {
	params ["_p", "_side", "_r"];
	private _en = [west, east, resistance] - [_side];
	{alive _x && {(side _x) in _en}} count (_p nearEntities [["CAManBase", "LandVehicle", "StaticWeapon"], _r])
};

//--- (de VIOC_irregular.sqf, IW_fnc_room) [hombres] -> true si caben en el presupuesto de IA (perf_cleanup; sin el, 650)
VIOC_AA_fnc_room = {
	params [["_n", 1]];
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", -1];
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
	if (!(_max isEqualType 0) || {!(_cnt isEqualType 0)} || {_max < 0} || {_cnt < 0}) then {_max = 650; _cnt = {!isPlayer _x} count allUnits};
	(_cnt + _n) <= (_max - VIOC_AA_AI_MARGIN)
};

//--- (de VIOC_irregular.sqf, IW_fnc_reserve) [hombres]: reserva en el recuento de perf_cleanup hasta su proximo recuento
VIOC_AA_fnc_reserve = {
	params ["_n"];
	isNil {
		private _c = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
		if ((_c isEqualType 0) && {_c >= 0}) then {missionNamespace setVariable ["VIOC_PERF_AI_COUNT", _c + _n]};
	};
};

//=====================================================================================================================
// Helicopteros, infanteria y precio
//=====================================================================================================================
//--- [bando] -> [nacion, mod] principales ("COL"/"US"/"RU"/"INS", "RHS"/"CUP")
VIOC_AA_fnc_nation = {
	params ["_side"];
	private _mn = missionNamespace getVariable [format ["CTI_%1_MAINNATIONS", _side], [-1, -1]];
	if (!(_mn isEqualType []) || {count _mn < 2}) then {_mn = [-1, -1]};
	private _n = _mn select 0;
	private _m = _mn select 1;
	private _tag = "";
	if (_n isEqualTo (missionNamespace getVariable ["CTI_COL_ID", -99])) then {_tag = "COL"};
	if (_n isEqualTo (missionNamespace getVariable ["CTI_US_ID", 2])) then {_tag = "US"};
	if (_n isEqualTo (missionNamespace getVariable ["CTI_SOV_ID", 3])) then {_tag = "RU"};
	if (_n isEqualTo (missionNamespace getVariable ["CTI_CHDKZ_ID", 7])) then {_tag = "INS"};
	private _mod = "";
	if (_m isEqualTo (missionNamespace getVariable ["CTI_RHS_ID", 5])) then {_mod = "RHS"};
	if (_m isEqualTo (missionNamespace getVariable ["CTI_CUP_ID", 4])) then {_mod = "CUP"};
	[_tag, _mod]
};

//--- [bando] -> nivel de la mejora aerea
VIOC_AA_fnc_airLevel = {
	params ["_side"];
	private _u = (_side) call CTI_CO_FNC_GetSideUpgrades;
	if (isNil "_u" || {!(_u isEqualType [])} || {count _u <= CTI_UPGRADE_AIR}) exitWith {0};
	private _l = _u select CTI_UPGRADE_AIR;
	if (_l isEqualType 0) then {_l} else {0}
};

//--- [clase, nivel aereo del bando, apoyo de EE. UU. a Colombia] -> true si el bando ya puede usarla
VIOC_AA_fnc_levelOk = {
	params ["_c", "_lvl", "_us"];
	private _info = missionNamespace getVariable [_c, []];
	private _need = 0;
	if (_info isEqualType [] && {count _info > CTI_UNIT_UPGRADE} && {(_info select CTI_UNIT_UPGRADE) isEqualType 0}) then {_need = _info select CTI_UNIT_UPGRADE};
	_need = _need min VIOC_AA_LEVEL_CAP;
	if (_us) then {_need = _need max VIOC_AA_LEVEL_CAP};
	_lvl >= _need
};

VIOC_AA_fnc_airOk = {
	params ["_c", "_side"];
	private _cfg = configFile >> "CfgVehicles" >> _c;
	isClass _cfg && {getNumber (_cfg >> "scope") >= 2} && {_c isKindOf "Helicopter"} && {(getNumber (_cfg >> "side")) == ([east, west, resistance, civilian] find _side)}
};

VIOC_AA_fnc_manOk = {
	params ["_c", "_side"];
	private _cfg = configFile >> "CfgVehicles" >> _c;
	isClass _cfg && {_c isKindOf "CAManBase"} && {(getNumber (_cfg >> "side")) == ([east, west, resistance, civilian] find _side)}
};

//--- [clase, precio si no tiene] -> precio de compra de la mision (CTI_UNIT_PRICE)
VIOC_AA_fnc_price = {
	params ["_c", "_def"];
	private _info = missionNamespace getVariable [_c, []];
	private _p = _def;
	if (_info isEqualType [] && {count _info > CTI_UNIT_PRICE} && {(_info select CTI_UNIT_PRICE) isEqualType 0}) then {_p = _info select CTI_UNIT_PRICE};
	if (_p <= 0) then {_p = _def};
	_p
};

//--- [bando, rol] -> [clase que se crea, clase de la lista que la habilita, nacion] o []
VIOC_AA_fnc_pickAir = {
	params ["_side", "_role"];
	private _list = missionNamespace getVariable [format ["CTI_%1_%2Units", _side, CTI_AIR], []];
	if !(_list isEqualType []) then {_list = []};
	_list = _list select {_x isEqualType ""};
	private _low = _list apply {toLower _x};
	if (count _low == 0) exitWith {[]};
	private _lvl = [_side] call VIOC_AA_fnc_airLevel;
	private _nat = [_side] call VIOC_AA_fnc_nation;
	private _tag = _nat select 0;
	private _mod = _nat select 1;
	private _desert = (missionNamespace getVariable ["CTI_CAMO_ACTIVATION", 0]) in [2, 7];
	private _cands = [];
	{
		_x params ["_r", "_t", "_m", "_cw", "_cd", "_gates"];
		if (_r == _role) then {
			private _us = (_t == "US") && {_tag == "COL"};
			private _gate = "";
			{
				if (((toLower _x) in _low) && {[_x, _lvl, _us] call VIOC_AA_fnc_levelOk}) exitWith {_gate = _x};
			} forEach _gates;
			if (_gate != "") then {
				private _cls = if (_desert && {_cd != ""}) then {_cd} else {_cw};
				if !([_cls, _side] call VIOC_AA_fnc_airOk) then {_cls = _gate};
				if ([_cls, _side] call VIOC_AA_fnc_airOk) then {_cands pushBack [_cls, _gate, _t, ([0, 2] select (_t == _tag)) + ([0, 1] select (_m == _mod))]};
			};
		};
	} forEach VIOC_AA_TABLE;
	//--- sin fila de la tabla: el helicoptero mas barato de la lista con asientos suficientes (solo transporte)
	if (count _cands == 0 && {_role in ["bh", "ch"]}) then {
		private _need = [8, 14] select (_role == "ch");
		private _best = "";
		private _bp = 1e12;
		{
			private _usF = (_tag == "COL") && {((toLower (getText (configFile >> "CfgVehicles" >> _x >> "faction"))) find "rhs_faction_us") == 0};
			if (([_x, _side] call VIOC_AA_fnc_airOk) && {(getNumber (configFile >> "CfgVehicles" >> _x >> "transportSoldier")) >= _need} && {[_x, _lvl, _usF] call VIOC_AA_fnc_levelOk}) then {
				private _p = [_x, VIOC_AA_HELI_DEF] call VIOC_AA_fnc_price;
				if (_p < _bp) then {_bp = _p; _best = _x};
			};
		} forEach _list;
		if (_best != "") then {_cands pushBack [_best, _best, _tag, 0]};
	};
	if (count _cands == 0) exitWith {[]};
	//--- escolta: una nacion al azar entre las que hay (mision B: Colombia o EE. UU. por igual); transporte: la mejor puntuacion
	if (_role == "esc") then {
		private _tags = [];
		{_tags pushBackUnique (_x select 2)} forEach _cands;
		private _tg = selectRandom _tags;
		_cands = _cands select {(_x select 2) == _tg};
	};
	private _best = _cands select 0;
	{if ((_x select 3) > (_best select 3)) then {_best = _x}} forEach _cands;
	[_best select 0, _best select 1, _best select 2]
};

//--- [bando] -> [todas, ametralladoras, antitanque, jefes]: clases de las listas de pueblo del bando
VIOC_AA_fnc_infPool = {
	params ["_side"];
	private _tag = ["WEST_", "EAST_"] select (_side isEqualTo east);
	private _get = {
		params ["_k"];
		private _l = missionNamespace getVariable [_tag + _k, []];
		if !(_l isEqualType []) then {_l = []};
		private _r = [];
		{
			private _c = if (_x isEqualType []) then {_x param [0, ""]} else {_x};
			if ((_c isEqualType "") && {_c != ""} && {[_c, _side] call VIOC_AA_fnc_manOk}) then {_r pushBackUnique _c};
		} forEach _l;
		_r
	};
	private _li = ["INFANTRY_SQ_LIGHT"] call _get;
	private _mg = ["INFANTRY_SQ_MG"] call _get;
	private _at = ["INFANTRY_SQ_AT"] call _get;
	private _all = +_li;
	{_all pushBackUnique _x} forEach (_mg + _at);
	private _lead = _all select {
		private _n = toLower _x;
		(["lider", "leader", "officer", "comandante", "_sl", "_tl", "teamlead", "squadlead", "sergeant"] findIf {(_n find _x) >= 0}) >= 0
	};
	[_all, _mg - _li, _at - _li, _lead]
};

//--- [pool, hombres] -> clases: jefe, 1 (2 con 12 o mas) ametrallador y antitanque, el resto fusileros de la lista
VIOC_AA_fnc_infClasses = {
	params ["_pool", "_n"];
	private _all = _pool select 0;
	private _mg = _pool select 1;
	private _at = _pool select 2;
	private _lead = _pool select 3;
	private _res = [if (count _lead > 0) then {selectRandom _lead} else {selectRandom _all}];
	private _k = [1, 2] select (_n >= 12);
	for "_j" from 1 to _k do {_res pushBack (selectRandom ([_all, _mg] select (count _mg > 0)))};
	for "_j" from 1 to _k do {_res pushBack (selectRandom ([_all, _at] select (count _at > 0)))};
	private _rest = _all - _lead;
	if (count _rest == 0) then {_rest = _all};
	while {count _res < _n} do {_res pushBack (selectRandom _rest)};
	_res resize (_n min (count _res));
	_res
};

//--- (de VIOC_specops.sqf, soPayer) quien paga: ["commander", grpNull] / ["team", grupo] / [] si nadie puede
VIOC_AA_fnc_payer = {
	params ["_side", "_price"];
	private _logic = _side call CTI_CO_FNC_GetSideLogic;
	if (isNil "_logic" || {!(_logic isEqualType objNull)} || {isNull _logic}) exitWith {[]};
	private _cmd = _logic getVariable ["cti_commander", grpNull];
	if !(_cmd isEqualType grpNull) then {_cmd = grpNull};
	private _human = !isNull _cmd && {isPlayer leader _cmd};
	if (!_human) exitWith {
		private _f = _side call CTI_CO_FNC_GetFundsCommander;
		if (!isNil "_f" && {_f isEqualType 0} && {_f >= (_price + VIOC_AA_RESERVE)}) then {["commander", grpNull]} else {[]}
	};
	private _best = grpNull;
	private _bf = -1;
	{
		if (!isNull _x && {!(_x isEqualTo _cmd)} && {!isPlayer leader _x}) then {
			private _f = _x call CTI_CO_FNC_GetFundsTeam;
			if (!isNil "_f" && {_f isEqualType 0} && {_f > _bf}) then {_bf = _f; _best = _x};
		};
	} forEach (_side call CTI_CO_FNC_GetSideGroups);
	if (!isNull _best && {_bf >= (_price + VIOC_AA_RESERVE_TEAM)}) then {["team", _best]} else {[]}
};

//--- (de VIOC_specops.sqf, soCharge) [bando, pagador, cantidad] (negativa = cobrar, positiva = devolver)
VIOC_AA_fnc_charge = {
	params ["_side", "_payer", "_amount"];
	if (count _payer == 0 || {_amount == 0}) exitWith {};
	if ((_payer select 0) == "commander") then {
		[_side, _amount] call CTI_CO_FNC_ChangeFundsCommander;
	} else {
		if ((_payer select 0) == "team" && {!isNull (_payer select 1)}) then {[_payer select 1, _amount] call CTI_CO_FNC_ChangeFundsTeam};
	};
};

//=====================================================================================================================
// Salida, objetivo y zona de aterrizaje
//=====================================================================================================================
//--- [punto ILS, pueblo duenio] de cada aeropuerto de CfgWorlds (principal y SecondaryAirports; la regla de airfields)
VIOC_AA_fnc_airfields = {
	private _w = configFile >> "CfgWorlds" >> worldName;
	private _cfgs = [_w];
	if (isClass (_w >> "SecondaryAirports")) then {_cfgs append ("true" configClasses (_w >> "SecondaryAirports"))};
	private _res = [];
	{
		private _p = getArray (_x >> "ilsPosition");
		if (count _p >= 2 && {(_p select 0) isEqualType 0} && {(_p select 1) isEqualType 0} && {((_p select 0) > 0) || {(_p select 1) > 0}}) then {
			private _pt = [_p select 0, _p select 1, 0];
			private _best = objNull;
			private _bd = 1500;
			{
				private _d = _x distance2D _pt;
				if (_d < _bd) then {_bd = _d; _best = _x};
			} forEach CTI_Towns;
			if (!isNull _best) then {_res pushBack [_pt, _best]};
		};
	} forEach _cfgs;
	_res
};

//--- [bando] -> puntos de salida [[posicion, nombre], ...]: fabricas aereas vivas y aerodromos propios, sin enemigos cerca
VIOC_AA_fnc_origins = {
	params ["_side"];
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _res = [];
	{
		if (alive _x) then {_res pushBack [getPosATL _x, "la fabrica aerea"]};
	} forEach ([CTI_AIR, (_side) call CTI_CO_FNC_GetSideStructures] call CTI_CO_FNC_GetSideStructuresByType);
	{
		_x params ["_p", "_t"];
		if (!isNull _t && {(_t getVariable ["cti_town_sideID", -1]) == _sid}) then {_res pushBack [_p, format ["el aerodromo de %1", _t getVariable ["cti_town_name", "?"]]]};
	} forEach VIOC_AA_AIRF;
	_res select {([_x select 0, _side, VIOC_AA_SAFE_ORIGIN] call VIOC_AA_fnc_enemyCount) < 3}
};

//--- [bando] -> [[pueblo, peso], ...]: los pueblos no propios del frente (de VIOC_specops.sqf, soPickTarget)
VIOC_AA_fnc_targets = {
	params ["_side"];
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _anchors = (CTI_Towns select {(_x getVariable ["cti_town_sideID", -1]) == _sid}) apply {getPosATL _x};
	private _base = [_side] call VIOC_AA_fnc_base;
	if (count _base > 1) then {_anchors pushBack _base};
	if (count _anchors == 0) exitWith {[]};
	private _busy = if (isNil "VIOC_fnc_soBusyTowns") then {[]} else {[_side] call VIOC_fnc_soBusyTowns};
	//--- ai_tactics: pueblos perdidos que el bando quiere recuperar (pedidos de contraataque abiertos)
	private _ca = [];
	{
		if ((_x isEqualType VIOC_AA_HM) && {!(_x getOrDefault ["done", true])} && {(_x getOrDefault ["side", sideUnknown]) isEqualTo _side}) then {_ca pushBack (_x getOrDefault ["town", objNull])};
	} forEach (missionNamespace getVariable ["VIOC_TAC_REQ", []]);
	//--- pueblos hacia los que ya van escuadras IA del bando (orden de la mision)
	private _goal = [];
	{
		private _p = _x getVariable ["cti_order_pos", objNull];
		if ((_p isEqualType objNull) && {!isNull _p} && {_p in CTI_Towns}) then {_goal pushBackUnique _p};
	} forEach ((_side) call CTI_CO_FNC_GetSideGroups);
	private _cdVar = format ["vioc_aa_cd%1", _sid];
	private _towns = [];
	private _list = [];
	{
		private _t = _x;
		if (((_t getVariable ["cti_town_sideID", -1]) != _sid) && {!(_t in _busy)} && {(_t getVariable [_cdVar, -1]) < time}) then {
			private _d = 1e9;
			{_d = _d min (_x distance2D _t)} forEach _anchors;
			if (_d < VIOC_AA_FRONT_MAX) then {
				_list pushBack [_d, count _towns];
				_towns pushBack _t;
			};
		};
	} forEach CTI_Towns;
	if (count _list == 0) exitWith {[]};
	_list sort true;
	private _d0 = (_list select 0) select 0;
	_list = _list select {(_x select 0) <= (_d0 + VIOC_AA_FRONT)};
	if (count _list > 5) then {_list resize 5};
	private _res = [];
	{
		private _t = _towns select (_x select 1);
		private _w = 5 - _forEachIndex;
		if (_t in _ca) then {_w = _w * 3};
		if (_t in _goal) then {_w = _w * 2};
		_res pushBack [_t, _w];
	} forEach _list;
	_res
};

//--- [vehiculo o estatica] -> true si es antiaerea: misiles de airLock 2 o balas de "hit" >= VIOC_AA_GUN_HIT (canones)
VIOC_AA_fnc_isAA = {
	params ["_v"];
	private _t = typeOf _v;
	private _c = VIOC_AA_AACACHE getOrDefault [_t, -1];
	if (_c isEqualType true) exitWith {_c};
	private _aa = ((magazinesAllTurrets _v) findIf {
		private _ac = configFile >> "CfgAmmo" >> (getText (configFile >> "CfgMagazines" >> (_x select 0) >> "ammo"));
		((getNumber (_ac >> "airLock")) >= 2) || {((getText (_ac >> "simulation")) == "shotBullet") && {(getNumber (_ac >> "hit")) >= VIOC_AA_GUN_HIT}}
	}) >= 0;
	VIOC_AA_AACACHE set [_t, _aa];
	_aa
};

//--- [pueblo, desde, bando, Chinook] -> zona de aterrizaje [x, y, 0] o [] (de VIOC_specops.sqf, soFindLZ: mismas pruebas de
//--- llano y despejado de BIS_fnc_findSafePos; aqui a 400-600 m, 80 intentos (40 del lado de la salida), claro del tamano del
//--- rotor (10 m; 15 m el Chinook; arbustos 5/8 m) y sin antiaereas, blindados ni enemigos cerca)
VIOC_AA_fnc_findLZ = {
	params ["_town", "_from", "_side", "_heavy"];
	private _tp = getPosATL _town;
	private _dir = _tp getDir _from;
	private _bad = [_side] call VIOC_AA_fnc_enemyBases;
	private _en = [west, east, resistance] - [_side];
	//--- amenazas fuertes cerca del pueblo (una sola busqueda): antiaereas (tripuladas por el enemigo o vacias) y blindados
	private _aa = [];
	private _tk = [];
	{
		if (alive _x) then {
			private _crewed = (count (crew _x)) > 0;
			if (!_crewed || {(side _x) in _en}) then {
				if ([_x] call VIOC_AA_fnc_isAA) then {_aa pushBack (getPosATL _x)} else {
					if (_crewed && {_x isKindOf "Tank"}) then {_tk pushBack (getPosATL _x)};
				};
			};
		};
	} forEach (_tp nearEntities [["StaticWeapon", "LandVehicle"], (VIOC_AA_LZ_R select 1) + VIOC_AA_AA_R]);
	private _landR = [40, 55] select _heavy;
	private _flatR = [10, 14] select _heavy;
	private _objR = [10, 15] select _heavy;		//--- rotor del UH-60 ~16 m, CH-47 ~30 m de largo
	private _bushR = [5, 8] select _heavy;		//--- los arbustos solo debajo del fuselaje
	private _vehR = [15, 20] select _heavy;
	private _r0 = VIOC_AA_LZ_R select 0;
	private _rv = (VIOC_AA_LZ_R select 1) - _r0;
	private _ws = worldSize;
	private _res = [];
	for "_i" from 0 to 79 do {
		private _spread = [70, 180] select (_i >= 40);
		private _q = _tp getPos [_r0 + random _rv, _dir - _spread + random (2 * _spread)];
		private _p = [_q select 0, _q select 1, 0];
		if (((_p select 0) > 100) && {(_p select 1) > 100} && {(_p select 0) < (_ws - 100)} && {(_p select 1) < (_ws - 100)}
			&& {[_p, _landR] call VIOC_AA_fnc_isLand} && {[_p, _tp] call VIOC_AA_fnc_dry}
			&& {(_bad findIf {(_x distance2D _p) < VIOC_AA_BASE_R}) < 0}
			&& {(_aa findIf {(_x distance2D _p) < VIOC_AA_AA_R}) < 0}
			&& {(_tk findIf {(_x distance2D _p) < VIOC_AA_TANK_R}) < 0}
			&& {!((_p isFlatEmpty [-1, -1, 0.3, _flatR, 0, false]) isEqualTo [])}
			&& {(nearestTerrainObjects [_p, ["TREE", "SMALL TREE", "BUILDING", "HOUSE", "ROCK", "ROCKS", "WALL", "FENCE", "POWER LINES", "TRANSMITTER", "RUIN", "BUNKER", "FORTRESS", "VIEW-TOWER", "WATERTOWER", "LIGHTHOUSE", "CHURCH", "CHAPEL", "CROSS", "FUELSTATION", "HOSPITAL", "STACK", "QUAY"], _objR, false, true]) isEqualTo []}
			&& {(nearestTerrainObjects [_p, ["BUSH"], _bushR, false, true]) isEqualTo []}
			&& {(nearestObjects [_p, ["AllVehicles", "Static"], _vehR]) isEqualTo []}
			&& {([_p, _side, VIOC_AA_INF_R] call VIOC_AA_fnc_enemyCount) < VIOC_AA_INF_MAX}) exitWith {_res = _p};
	};
	_res
};

//=====================================================================================================================
// Vuelo
//=====================================================================================================================
//--- [bando, clase, posicion 2D, rumbo, altura] -> [helicoptero, grupo] o el motivo (texto). Volando, con su tripulacion IA
//--- del bando (createVehicleCrew, como VIOC_air_support_server.sqf), descuidado y sin disparar.
VIOC_AA_fnc_spawnAir = {
	params ["_side", "_cls", "_pos", "_dir", "_alt"];
	private _veh = createVehicle [_cls, [_pos select 0, _pos select 1, _alt], [], 0, "FLY"];
	if (isNull _veh) exitWith {"no se pudo crear el helicoptero"};
	_veh setDir _dir;
	_veh setPosASL [_pos select 0, _pos select 1, ((getTerrainHeightASL _pos) max 0) + _alt];
	_veh setVelocityModelSpace [0, 40, 0];
	_veh setVariable ["vioc_aa", true, true];
	_veh setVariable ["vioc_specops", true, true];	//--- airfields (servicio y regreso a base) y ai_transport no lo tocan
	_veh setVariable ["VIOC_KEEP", true, true];		//--- perf_cleanup no lo borra: lo borra este archivo
	_veh lock 2;
	_veh allowCrewInImmobile true;
	private _cg = createVehicleCrew _veh;
	if (isNil "_cg" || {!(_cg isEqualType grpNull)} || {isNull _cg}) then {_cg = group (driver _veh)};
	if (isNull (driver _veh)) exitWith {
		{deleteVehicle _x} forEach (crew _veh);
		deleteVehicle _veh;
		"el helicoptero no recibio tripulacion IA"
	};
	if !((side _cg) isEqualTo _side) then {
		private _old = _cg;
		_cg = createGroup [_side, true];
		if (!isNull _cg) then {
			(crew _veh) joinSilent _cg;
			if ((count (units _old)) == 0) then {deleteGroup _old};
		};
	};
	if (isNull _cg || {!((side _cg) isEqualTo _side)}) exitWith {
		{deleteVehicle _x} forEach (crew _veh);
		deleteVehicle _veh;
		"la tripulacion no es del bando"
	};
	{
		_x setVariable ["vioc_aa", true];
		_x allowFleeing 0;
	} forEach (crew _veh);
	_cg setVariable ["vioc_aa", true];
	_cg setVariable ["vioc_specops", true, true];
	_cg setBehaviour "CARELESS";
	_cg setCombatMode "BLUE";
	_cg setSpeedMode "FULL";
	_cg allowFleeing 0;
	_veh flyInHeight _alt;
	if (!isNil "VIOC_ZEUS" && {VIOC_ZEUS isEqualType objNull} && {!isNull VIOC_ZEUS}) then {VIOC_ZEUS addCuratorEditableObjects [[_veh] + (crew _veh), true]};
	[_veh, _cg]
};

//--- [helicoptero, grupo, salida, rumbo de salida]: llega a la salida (o pasa el plazo); si hay jugadores cerca se aleja otros
//--- 2,5 km por el mismo rumbo (2 veces como mucho), espera a que no haya jugadores cerca y lo borra con su tripulacion y lo
//--- que lleve dentro (nunca con un jugador dentro); si cayo, los restos quedan para el recolector de la mision
VIOC_AA_fnc_airGone = {
	params ["_veh", "_cg", "_exit", ["_dirOut", -1]];
	private _t = time + 900;
	waitUntil {sleep 5; !alive _veh || {(_veh distance2D _exit) < 500} || {time > _t}};
	private _k = 0;
	while {(_k < 2) && {_dirOut >= 0} && {alive _veh} && {canMove _veh} && {alive (driver _veh)} && {[[_veh], VIOC_AA_AIR_FREE_R] call VIOC_AA_fnc_playersNear}} do {
		_k = _k + 1;
		private _far = [_veh getPos [2500, _dirOut]] call VIOC_AA_fnc_clamp;
		[_cg] call VIOC_AA_fnc_clearWp;
		private _wf = _cg addWaypoint [_far, 0];
		_wf setWaypointType "MOVE";
		_cg setCurrentWaypoint _wf;
		private _t2 = time + 240;
		waitUntil {sleep 5; !alive _veh || {(_veh distance2D _far) < 500} || {time > _t2}};
	};
	waitUntil {
		sleep 5;
		private _objs = ((units _cg) + [_veh]) select {!isNull _x};
		!([_objs, VIOC_AA_AIR_FREE_R] call VIOC_AA_fnc_playersNear) || {(time > (_t + 1800)) && {!([_objs, 300] call VIOC_AA_fnc_playersNear)}}
	};
	if (alive _veh && {((crew _veh) findIf {isPlayer _x}) < 0}) then {
		{deleteVehicle _x} forEach (crew _veh);
		deleteVehicle _veh;
	};
	{
		if (!isNull _x && {!isPlayer _x} && {isNull objectParent _x || {!alive (objectParent _x)}}) then {deleteVehicle _x};
	} forEach (units _cg);
	if (!isNull _cg && {(count (units _cg)) == 0}) then {deleteGroup _cg};
};

//--- (de VIOC_ai_tactics.sqf, assaultWp, y VIOC_specops.sqf, soAssault) [grupo, pueblo, desde]: ir, buscar y destruir,
//--- centro del pueblo (captura), en bucle
VIOC_AA_fnc_assaultWp = {
	params ["_g", "_town", "_from"];
	private _tp = getPosATL _town;
	_tp = [_tp select 0, _tp select 1, 0];
	[_g] call VIOC_AA_fnc_clearWp;
	_g setCombatMode "RED";
	_g setBehaviour "AWARE";
	_g setSpeedMode "NORMAL";
	_g allowFleeing 0;
	private _app = _tp getPos [180, _tp getDir _from];
	private _first = [];
	if (!(surfaceIsWater _app) && {(_app distance2D _from) > 120}) then {
		_first = _g addWaypoint [[_app select 0, _app select 1, 0], 20];
		_first setWaypointType "MOVE";
		_first setWaypointBehaviour "AWARE";
		_first setWaypointCombatMode "RED";
		_first setWaypointSpeed "NORMAL";
		_first setWaypointFormation "WEDGE";
		_first setWaypointCompletionRadius 40;
	};
	private _w1 = _g addWaypoint [_tp, 30];
	_w1 setWaypointType "SAD";
	_w1 setWaypointBehaviour "COMBAT";
	_w1 setWaypointCombatMode "RED";
	_w1 setWaypointCompletionRadius 50;
	if (count _first == 0) then {_first = _w1};
	private _w2 = _g addWaypoint [_tp, 0];
	_w2 setWaypointType "MOVE";
	_w2 setWaypointCompletionRadius 15;
	private _wc = _g addWaypoint [_tp, 40];
	_wc setWaypointType "CYCLE";
	_g setCurrentWaypoint _first;
};

//--- [asalto]: escolta. Aparece junto al transporte, va a la zona de aterrizaje y da vueltas (LOITER) atacando lo que ve,
//--- VIOC_AA_LOITER s y hasta 3 min despues del aterrizaje (VIOC_AA_LOITER_MAX como mucho), y vuelve
VIOC_AA_fnc_escort = {
	params ["_op"];
	private _side = _op get "side";
	private _lz = _op get "lz";
	private _start = _op get "start";
	private _p0 = [_start getPos [250, (_start getDir _lz) + 90]] call VIOC_AA_fnc_clamp;
	private _air = [_side, _op get "esc", _p0, _p0 getDir _lz, VIOC_AA_ESC_ALT] call VIOC_AA_fnc_spawnAir;
	if (_air isEqualType "") exitWith {
		[_side, _op get "payer", _op get "escPrice"] call VIOC_AA_fnc_charge;
		[format ["asalto %1: sin escolta (%2); se devolvio su parte (%3)", _op get "id", _air, _op get "escPrice"]] call VIOC_AA_fnc_log;
	};
	private _veh = _air select 0;
	private _g = _air select 1;
	_op set ["escV", _veh];
	[5] call VIOC_AA_fnc_stat;
	_g setBehaviour "AWARE";
	_g setCombatMode "RED";
	_veh flyInHeight VIOC_AA_ESC_ALT;
	private _wp = _g addWaypoint [_lz, 0];
	_wp setWaypointType "LOITER";
	_wp setWaypointLoiterRadius VIOC_AA_LOITER_R;
	_wp setWaypointLoiterType "CIRCLE";
	_wp setWaypointBehaviour "AWARE";
	_wp setWaypointCombatMode "RED";
	_g setCurrentWaypoint _wp;
	private _t0 = time;
	waitUntil {sleep 5; !alive _veh || {(_veh distance2D _lz) < 700} || {time > (_t0 + 900)}};
	private _tArr = time;
	waitUntil {
		sleep 5;
		private _landed = _op getOrDefault ["landedT", -1];
		!alive _veh || {!canMove _veh} || {!alive (driver _veh)} || {(fuel _veh) < 0.2} || {(damage _veh) > 0.6} || {time > (_tArr + VIOC_AA_LOITER_MAX)}
			|| {(time > (_tArr + VIOC_AA_LOITER)) && {((_landed > 0) && {time > (_landed + 180)}) || {_op getOrDefault ["ended", false]}}}
	};
	if (alive _veh && {canMove _veh} && {alive (driver _veh)}) then {
		[_g] call VIOC_AA_fnc_clearWp;
		_g setBehaviour "CARELESS";
		_g setCombatMode "BLUE";
		_veh flyInHeight 150;
		private _w2 = _g addWaypoint [_start, 0];
		_w2 setWaypointType "MOVE";
		_g setCurrentWaypoint _w2;
		[format ["asalto %1: la escolta vuelve (%2 s sobre la zona)", _op get "id", round (time - _tArr)]] call VIOC_AA_fnc_log;
	};
	[_veh, _g, _start, _lz getDir _start] call VIOC_AA_fnc_airGone;
};

//--- [asalto, motivo, detalle]: libera al bando (una sola vez); "abort" devuelve el dinero del transporte y la infanteria
VIOC_AA_fnc_end = {
	params ["_op", "_why", ["_info", ""]];
	if (_op getOrDefault ["ended", false]) exitWith {};
	_op set ["ended", true];
	private _side = _op get "side";
	private _i = _op get "i";
	VIOC_AA_ACTIVE set [_i, false];
	if (_why == "abort") then {
		[_side, _op get "payer", (_op get "price") - (_op get "escPrice")] call VIOC_AA_fnc_charge;
		[4] call VIOC_AA_fnc_stat;
		VIOC_AA_NEXT set [_i, (VIOC_AA_NEXT select _i) min (time + VIOC_AA_RETRY)];
		[_side, format ["[Asalto aereo] El asalto aereo hacia %1 se cancelo (%2); se devolvio el dinero.", _op get "tname", _info]] call VIOC_AA_fnc_say;
	};
	VIOC_AA_LAST set [_i, format ["#%1 -> %2: %3 %4", _op get "id", _op get "tname", _why, _info]];
	[format ["asalto %1 (%2) termina: %3 %4", _op get "id", _side, _why, _info]] call VIOC_AA_fnc_log;
};

//--- [asalto, tomado]: la infanteria se queda en el pueblo (tomado) o se retira, y se borra sin jugadores cerca
VIOC_AA_fnc_infCleanup = {
	params ["_op", "_won"];
	private _team = _op get "team";
	_op set ["phase", "limpieza"];
	if (!isNull _team && {!_won}) then {
		//--- se retiran hacia su zona de aterrizaje y 800 m mas alla (del lado de su salida)
		private _lz = _op get "lz";
		private _back = [_lz getPos [800, (getPosATL (_op get "town")) getDir (_op get "origin")]] call VIOC_AA_fnc_clamp;
		if (surfaceIsWater _back) then {_back = +_lz};
		[_team] call VIOC_AA_fnc_clearWp;
		_team setCombatMode "YELLOW";
		private _wr = _team addWaypoint [_back, 50];
		_wr setWaypointType "MOVE";
		_wr setWaypointBehaviour "AWARE";
		_wr setWaypointSpeed "NORMAL";
		_team setCurrentWaypoint _wr;
	};
	if (!isNull _team) then {
		waitUntil {
			sleep 15;
			private _a = (units _team) select {alive _x};
			(count _a == 0) || {!([_a, VIOC_AA_FREE_R] call VIOC_AA_fnc_playersNear)}
		};
		{if (!isPlayer _x) then {deleteVehicle _x}} forEach (units _team);
		if ((count (units _team)) == 0) then {deleteGroup _team};
	};
	_op set ["phase", "hecho"];
	//--- se guardan los ultimos 8 terminados para la consola
	private _done = VIOC_AA_OPS select {(_x get "phase") == "hecho"};
	if (count _done > 8) then {
		private _drop = (_done select [0, (count _done) - 8]) apply {_x get "id"};
		VIOC_AA_OPS = VIOC_AA_OPS select {!((_x get "id") in _drop)};
	};
};

//=====================================================================================================================
// Asalto completo (spawn)
//=====================================================================================================================
VIOC_AA_fnc_runOp = {
	params ["_op"];
	private _side = _op get "side";
	private _sid = _op get "sid";
	private _town = _op get "town";
	private _tname = _op get "tname";
	private _lz = _op get "lz";
	private _start = _op get "start";
	private _origin = _op get "origin";
	private _id = _op get "id";
	//--- transporte con su tripulacion
	private _air = [_side, _op get "cls", _start, _start getDir _lz, VIOC_AA_ALT] call VIOC_AA_fnc_spawnAir;
	if (_air isEqualType "") exitWith {
		_op set ["phase", "hecho"];
		[_op, "abort", _air] call VIOC_AA_fnc_end;
		if ((_op get "escPrice") > 0) then {[_side, _op get "payer", _op get "escPrice"] call VIOC_AA_fnc_charge};
	};
	private _veh = _air select 0;
	private _cg = _air select 1;
	_op set ["veh", _veh];
	//--- infanteria (CTI_CO_FNC_CreateUnit: equipo de ai_loadouts y ropa de la mision), en tierra en el punto de salida y dentro
	private _team = createGroup [_side, true];
	_team setVariable ["vioc_aa", true];
	_team setVariable ["vioc_specops", true, true];	//--- ai_tactics, ai_transport y airfields no lo toman
	_op set ["team", _team];
	private _classes = _op get "classes";
	private _seats = _veh emptyPositions "Cargo";
	{
		if (_forEachIndex < _seats) then {
			private _u = [_x, _team, [_origin select 0, _origin select 1, 0], _side, false, "NONE"] call CTI_CO_FNC_CreateUnit;
			if (!isNil "_u" && {_u isEqualType objNull} && {!isNull _u}) then {
				_u setVariable ["vioc_aa", true];
				_u moveInCargo _veh;
				if !((vehicle _u) isEqualTo _veh) then {deleteVehicle _u};
			};
		};
	} forEach _classes;
	private _n = {alive _x && {(vehicle _x) isEqualTo _veh}} count (units _team);
	_op set ["n", _n];
	if (_n < 4) exitWith {
		{deleteVehicle _x} forEach (crew _veh);
		deleteVehicle _veh;
		{deleteVehicle _x} forEach (units _team);
		deleteGroup _team;
		_op set ["phase", "hecho"];
		[_op, "abort", format ["solo subieron %1 soldados", _n]] call VIOC_AA_fnc_end;
		if ((_op get "escPrice") > 0) then {[_side, _op get "payer", _op get "escPrice"] call VIOC_AA_fnc_charge};
	};
	_team setBehaviour "CARELESS";
	_team allowFleeing 0;
	if ((_op get "esc") != "") then {[_op] spawn VIOC_AA_fnc_escort};
	//--- vuelo bajo hasta la zona y aterrizaje (de VIOC_specops.sqf, soDoHeli)
	_op set ["phase", "vuelo"];
	private _pad = createVehicle ["Land_HelipadEmpty_F", _lz, [], 0, "NONE"];
	private _w1 = _cg addWaypoint [_lz, 0];
	_w1 setWaypointType "MOVE";
	_w1 setWaypointCompletionRadius 100;
	_cg setCurrentWaypoint _w1;
	private _deadline = time + ((_start distance2D _lz) / 25) + 240;
	private _landAt = -1;
	private _state = "";
	waitUntil {
		sleep 1;
		if (!alive _veh) then {_state = "dead"} else {
			if (!alive (driver _veh) || {!canMove _veh}) then {_state = "hit"};
		};
		if (_state == "") then {
			private _h = (getPosATL _veh) select 2;
			if (_landAt < 0 && {((_veh distance2D _lz) < 300) || {((_veh distance2D _lz) < 900) && {(speed _veh) < 20}}}) then {_veh land "GET OUT"; _landAt = time};
			if (_landAt > 0 && {(_h < 2) || {isTouchingGround _veh}} && {(speed _veh) < 10}) then {_state = "landed"};
			//--- con land "GET OUT" la IA de carga puede bajarse sola: si ya no queda nadie dentro, aterrizo
			if (_state == "" && {_landAt > 0} && {_h < 6} && {({alive _x && {(vehicle _x) isEqualTo _veh}} count (units _team)) == 0}) then {_state = "landed"};
			if (_state == "" && {_landAt > 0} && {time > (_landAt + 90)} && {_h < 4} && {(speed _veh) < 10}) then {_state = "landed"};
			if (_state == "" && {time > _deadline}) then {_state = "late"};
		};
		_state != ""
	};
	//--- alcanzado: hasta 60 s para ver si cae, aterriza de emergencia o sigue en el aire
	if (_state == "hit") then {
		private _t3 = time + 60;
		waitUntil {sleep 1; !alive _veh || {isTouchingGround _veh} || {((getPosATL _veh) select 2) < 3} || {time > _t3}};
		_state = if (!alive _veh) then {"dead"} else {if ((((getPosATL _veh) select 2) < 5) && {(speed _veh) < 15}) then {"forced"} else {"lost"}};
	};
	//--- retrasado: lejos se cancela; cerca, un ultimo intento de aterrizar (60 s)
	if (_state == "late") then {
		if (alive _veh && {canMove _veh} && {(_veh distance2D _lz) < 2500}) then {
			_veh land "GET OUT";
			private _t4 = time + 60;
			waitUntil {sleep 1; !alive _veh || {((getPosATL _veh) select 2) < 3} || {time > _t4}};
			if (!alive _veh) then {_state = "dead"} else {if ((((getPosATL _veh) select 2) < 4) && {(speed _veh) < 10}) then {_state = "landed"}};
		};
	};
	private _inside = (units _team) select {alive _x && {(vehicle _x) isEqualTo _veh}};
	switch (_state) do {
		case "dead": {
			//--- derribado: mueren los que van dentro
			{_x setDamage 1} forEach _inside;
			[2] call VIOC_AA_fnc_stat;
			_op set ["phase", "derribado"];
			[_side, format ["[Asalto aereo] El %1 del asalto hacia %2 fue derribado con %3 soldados a bordo.", [_op get "cls"] call VIOC_AA_fnc_name, _tname, count _inside]] call VIOC_AA_fnc_say;
			[_op, "derribado", format ["a %1 m de la zona", round (_veh distance2D _lz)]] call VIOC_AA_fnc_end;
			[_veh, _cg, _start, _lz getDir _start] spawn VIOC_AA_fnc_airGone;
			deleteVehicle _pad;
			[_op, false] call VIOC_AA_fnc_infCleanup;
		};
		case "lost": {
			//--- alcanzado y sin poder aterrizar: los que van dentro siguen su suerte con el helicoptero
			[2] call VIOC_AA_fnc_stat;
			_op set ["phase", "derribado"];
			[_side, format ["[Asalto aereo] El %1 del asalto hacia %2 fue alcanzado y no pudo aterrizar.", [_op get "cls"] call VIOC_AA_fnc_name, _tname]] call VIOC_AA_fnc_say;
			[_op, "alcanzado", ""] call VIOC_AA_fnc_end;
			[_veh, _cg, _start, _lz getDir _start] spawn VIOC_AA_fnc_airGone;
			deleteVehicle _pad;
			[_op, false] call VIOC_AA_fnc_infCleanup;
		};
		case "late": {
			//--- no llego: se cancela, se devuelve el dinero y el helicoptero vuelve con ellos (se borran juntos)
			_op set ["phase", "cancelado"];
			[_op, "abort", "el helicoptero no llego a la zona de aterrizaje"] call VIOC_AA_fnc_end;
			if (alive _veh) then {
				_veh land "NONE";
				_veh flyInHeight 120;
				[_cg] call VIOC_AA_fnc_clearWp;
				private _wa = _cg addWaypoint [_start, 0];
				_wa setWaypointType "MOVE";
				_cg setCurrentWaypoint _wa;
			};
			[_veh, _cg, _start, _lz getDir _start] spawn VIOC_AA_fnc_airGone;
			deleteVehicle _pad;
			[_op, true] call VIOC_AA_fnc_infCleanup;
		};
		default {
			//--- "landed" o "forced" (aterrizaje de emergencia): bajan y atacan
			_team leaveVehicle _veh;
			{
				_x allowDamage false;
				unassignVehicle _x;
				moveOut _x;
			} forEach _inside;
			_op set ["landedT", time];
			[1] call VIOC_AA_fnc_stat;
			sleep 2;
			{if (alive _x) then {_x allowDamage true}} forEach _inside;
			sleep 2;
			if (alive _veh && {canMove _veh} && {alive (driver _veh)}) then {
				_veh land "NONE";
				_veh flyInHeight 120;
				[_cg] call VIOC_AA_fnc_clearWp;
				private _w2 = _cg addWaypoint [_start, 0];
				_w2 setWaypointType "MOVE";
				_cg setCurrentWaypoint _w2;
			};
			[_veh, _cg, _start, _lz getDir _start] spawn VIOC_AA_fnc_airGone;
			[_pad] spawn {params ["_p"]; sleep 120; deleteVehicle _p};
			private _nAlive = {alive _x} count (units _team);
			private _lp = if (_nAlive > 0) then {getPosATL (leader _team)} else {+_lz};
			_team setBehaviour "AWARE";
			_team setCombatMode "RED";
			_op set ["phase", "asalto"];
			if (_nAlive > 0) then {
				[_team, _town, _lp] call VIOC_AA_fnc_assaultWp;
				[_side, format ["[Asalto aereo] %1 soldados desembarcaron a %2 m de %3 y atacan%4.", _nAlive, round (_lp distance2D _town), _tname,
					["", " (aterrizaje de emergencia)"] select (_state == "forced")]] call VIOC_AA_fnc_say;
			};
			//--- asalto: hasta tomar el pueblo (+ VIOC_AA_HOLD s), VIOC_AA_LIFETIME s o quedar 1 hombre
			private _t0 = time;
			private _won = -1;
			private _end = "";
			while {_end == ""} do {
				sleep 15;
				private _alive = (units _team) select {alive _x};
				if (count _alive == 0) then {_end = "eliminados"};
				if (_end == "") then {
					//--- supervivientes que siguen dentro de un helicoptero caido o quieto en tierra: afuera
					{
						private _v = vehicle _x;
						if (!(_v isEqualTo _x) && {_v isKindOf "Air"} && {!alive _v || {isTouchingGround _v && {(speed _v) < 3}}}) then {unassignVehicle _x; moveOut _x};
					} forEach _alive;
					if (_won < 0 && {(_town getVariable ["cti_town_sideID", -1]) == _sid}) then {
						_won = time;
						[3] call VIOC_AA_fnc_stat;
						_op set ["phase", "tomado"];
						[format ["asalto %1: %2 tomado", _id, _tname]] call VIOC_AA_fnc_log;
					};
					if (_won > 0 && {(time - _won) > VIOC_AA_HOLD}) then {_end = "pueblo tomado"};
					if (_won < 0 && {(time - _t0) > VIOC_AA_LIFETIME}) then {_end = "tiempo de asalto agotado"};
					if (_won < 0 && {count _alive < 2}) then {_end = "diezmados"};
				};
			};
			[_op, _end, format ["%1 vivos de %2", {alive _x} count (units _team), _op get "n"]] call VIOC_AA_fnc_end;
			[_op, _won > 0] call VIOC_AA_fnc_infCleanup;
		};
	};
};

//=====================================================================================================================
// Plan y lanzamiento
//=====================================================================================================================
//--- [bando, gratis, transporte ("" al azar, "bh", "ch"), escolta (-1 al azar, 0 no, 1 si)] -> "ok" o el motivo.
//--- Sin pausas: se puede llamar desde la consola. Elige todo, cobra (sin interrupciones entre mirar y descontar) y lanza.
VIOC_AA_fnc_plan = {
	params ["_side", ["_free", false], ["_want", ""], ["_wantEsc", -1]];
	if !(_side in [west, east]) exitWith {"bando no valido"};
	private _i = [_side] call VIOC_AA_fnc_idx;
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	if (VIOC_AA_ACTIVE select _i) exitWith {"ya hay un asalto aereo en curso de este bando"};
	private _mine = {alive _x && {_x getVariable ["vioc_aa", false]} && {(side group _x) isEqualTo _side}} count allUnits;
	//--- (revision M1) el tope cuenta lo que ya vive MAS el asalto nuevo; aqui, con el mas chico (Black Hawk sin escolta)
	if ((_mine + VIOC_AA_N_BH + VIOC_AA_CREW_BH) > VIOC_AA_SIDE_CAP) exitWith {format ["quedan %1 hombres de asaltos anteriores (tope %2 con el nuevo)", _mine, VIOC_AA_SIDE_CAP]};
	private _origins = [_side] call VIOC_AA_fnc_origins;
	if (count _origins == 0) exitWith {"sin fabrica aerea ni aerodromo propio (o estan disputados)"};
	private _bh = [_side, "bh"] call VIOC_AA_fnc_pickAir;
	if (count _bh == 0) exitWith {"sin helicoptero de transporte en la lista de la fabrica aerea a este nivel"};
	private _pool = [_side] call VIOC_AA_fnc_infPool;
	if (count (_pool select 0) == 0) exitWith {"sin listas de infanteria del bando"};
	private _ch = [];
	if (_want == "ch" || {_want == "" && {(random 100) < VIOC_AA_P_HEAVY}}) then {_ch = [_side, "ch"] call VIOC_AA_fnc_pickAir};
	private _heavy = count _ch > 0;
	private _esc = [];
	if (_wantEsc == 1 || {_wantEsc < 0 && {(random 100) < VIOC_AA_P_ESC}}) then {_esc = [_side, "esc"] call VIOC_AA_fnc_pickAir};
	//--- objetivo, punto de salida y zona de aterrizaje: hasta 3 pueblos del frente
	private _cands = [_side] call VIOC_AA_fnc_targets;
	if (count _cands == 0) exitWith {"sin pueblos enemigos o neutrales en el frente"};
	private _town = objNull;
	private _lz = [];
	private _org = [];
	for "_k" from 1 to 3 do {
		if ((count _cands == 0) || {count _lz > 0}) exitWith {};
		private _j = [_cands apply {_x select 1}] call VIOC_AA_fnc_pickIdx;
		private _t = (_cands select _j) select 0;
		_cands deleteAt _j;
		private _o = [];
		private _bd = 1e9;
		{
			private _d = (_x select 0) distance2D _t;
			if ((_d >= VIOC_AA_MIN_DIST) && {_d <= VIOC_AA_MAX_DIST} && {_d < _bd}) then {_bd = _d; _o = _x};
		} forEach _origins;
		if (count _o > 0) then {
			private _p = [_t, _o select 0, _side, _heavy] call VIOC_AA_fnc_findLZ;
			if ((count _p == 0) && {_heavy}) then {
				_p = [_t, _o select 0, _side, false] call VIOC_AA_fnc_findLZ;
				if (count _p > 0) then {_heavy = false};
			};
			if (count _p > 0) then {_town = _t; _lz = _p; _org = _o} else {_t setVariable [format ["vioc_aa_cd%1", _sid], time + VIOC_AA_TOWN_CD_FAIL]};
		};
	};
	if (isNull _town) exitWith {"sin zona de aterrizaje segura (llana, en tierra, sin antiaereas ni enemigos fuertes) a 400-600 m de los pueblos del frente, o el frente esta a menos de 1500 m de la salida"};
	//--- opciones en orden de preferencia: [Chinook, con escolta]; se descartan las que no caben en el presupuesto de IA
	private _nCH = 0;
	if (_heavy) then {
		_nCH = ((VIOC_AA_N_CH select 0) + floor random (1 + (VIOC_AA_N_CH select 1) - (VIOC_AA_N_CH select 0))) min (getNumber (configFile >> "CfgVehicles" >> (_ch select 0) >> "transportSoldier"));
		if (_nCH < 10) then {_heavy = false};
	};
	private _nBH = VIOC_AA_N_BH min (getNumber (configFile >> "CfgVehicles" >> (_bh select 0) >> "transportSoldier"));
	if (_nBH < 6) exitWith {format ["el %1 tiene menos de 6 asientos", _bh select 0]};
	private _classesAll = [_pool, [_nBH, _nCH] select _heavy] call VIOC_AA_fnc_infClasses;
	private _pEsc = if (count _esc > 0) then {round (VIOC_AA_FLIGHT * ([_esc select 1, VIOC_AA_HELI_DEF] call VIOC_AA_fnc_price))} else {0};
	private _opts = [];
	{
		private _hv = _x select 0;
		private _we = _x select 1;
		if ((!_hv || {_heavy}) && {!_we || {count _esc > 0}}) then {
			private _tr = [_bh, _ch] select _hv;
			private _nx = [_nBH, _nCH] select _hv;
			private _cl = _classesAll select [0, _nx];
			private _pInf = 0;
			{_pInf = _pInf + ([_x, VIOC_AA_UNIT_DEF] call VIOC_AA_fnc_price)} forEach _cl;
			private _pTr = round (VIOC_AA_FLIGHT * ([_tr select 1, VIOC_AA_HELI_DEF] call VIOC_AA_fnc_price));
			private _need = _nx + ([VIOC_AA_CREW_BH, VIOC_AA_CREW_CH] select _hv) + ([0, VIOC_AA_CREW_ESC] select _we);
			if (([_need] call VIOC_AA_fnc_room) && {(_mine + _need) <= VIOC_AA_SIDE_CAP}) then {_opts pushBack [_hv, _we, _tr, _cl, round _pInf, _pTr, [0, _pEsc] select _we, _need]};
		};
	} forEach [[true, true], [true, false], [false, true], [false, false]];
	if (count _opts == 0) exitWith {format ["presupuesto de IA lleno (VIOC_PERF_AI_MAX menos %1) o tope del bando (%2 vivos de asaltos, tope %3)", VIOC_AA_AI_MARGIN, _mine, VIOC_AA_SIDE_CAP]};
	//--- pago: la primera opcion que el pagador puede pagar (si no alcanza: sin escolta, despues Black Hawk)
	private _payer = [];
	private _sel = [];
	if (_free) then {
		_payer = ["free", grpNull];
		_sel = _opts select 0;
		_sel set [4, 0];
		_sel set [5, 0];
		_sel set [6, 0];
	} else {
		isNil {
			{
				private _pr = (_x select 4) + (_x select 5) + (_x select 6);
				private _py = [_side, _pr] call VIOC_AA_fnc_payer;
				if (count _py > 0) exitWith {_payer = _py; _sel = _x};
			} forEach _opts;
			if (count _payer > 0) then {[_side, _payer, -((_sel select 4) + (_sel select 5) + (_sel select 6))] call VIOC_AA_fnc_charge};
		};
	};
	if (count _payer == 0) exitWith {
		private _o = _opts select ((count _opts) - 1);
		format ["sin fondos (un asalto cuesta %1 como minimo, y el comandante IA conserva %2)", (_o select 4) + (_o select 5) + (_o select 6), VIOC_AA_RESERVE]
	};
	_sel params ["_hv", "_we", "_tr", "_cl", "_pInf", "_pTr", "_pE", "_need"];
	private _price = _pInf + _pTr + _pE;
	//--- lanzamiento
	_town setVariable [format ["vioc_aa_cd%1", _sid], time + VIOC_AA_TOWN_CD];
	VIOC_AA_ACTIVE set [_i, true];
	VIOC_AA_NEXT set [_i, time + ((VIOC_AA_EVERY max 5) * 60)];
	[_need] call VIOC_AA_fnc_reserve;
	private _op0 = _org select 0;
	private _start = [_op0 getPos [VIOC_AA_SPAWN_BACK, (_op0 getDir _lz) + 180]] call VIOC_AA_fnc_clamp;
	VIOC_AA_ID = VIOC_AA_ID + 1;
	private _tname = _town getVariable ["cti_town_name", "el pueblo"];
	private _escCls = if (_we) then {_esc select 0} else {""};
	private _op = createHashMapFromArray [["id", VIOC_AA_ID], ["side", _side], ["sid", _sid], ["i", _i], ["town", _town], ["tname", _tname],
		["lz", _lz], ["origin", _op0], ["oname", _org select 1], ["start", _start], ["cls", _tr select 0], ["heavy", _hv], ["classes", _cl],
		["esc", _escCls], ["price", _price], ["escPrice", _pE], ["payer", _payer], ["t0", time], ["phase", "salida"], ["n", count _cl],
		["team", grpNull], ["veh", objNull], ["escV", objNull], ["landedT", -1], ["ended", false]];
	VIOC_AA_OPS pushBack _op;
	[0] call VIOC_AA_fnc_stat;
	if (_hv) then {[6] call VIOC_AA_fnc_stat};
	private _escTxt = if (_we) then {format [", escoltado por un %1", [_escCls] call VIOC_AA_fnc_name]} else {""};
	[_side, format ["[Asalto aereo] Asalto aereo hacia %1: %2 con %3 soldados%4 (salida: %5; costo %6).", _tname, [_tr select 0] call VIOC_AA_fnc_name,
		count _cl, _escTxt, _org select 1, if (_free) then {"gratis, prueba"} else {str _price}]] call VIOC_AA_fnc_say;
	[format ["asalto %1 de %2: %3 (%4 por %5) con %6 hombres hacia %7, zona a %8 m, salida %9, escolta %10, paga %11, IA reservada %12", VIOC_AA_ID, _side,
		_tr select 0, _tr select 1, _tr select 2, count _cl, _tname, round (_lz distance2D _town), _org select 1, _escCls, _payer select 0, _need]] call VIOC_AA_fnc_log;
	VIOC_AA_LAST set [_i, format ["#%1 -> %2: en camino", VIOC_AA_ID, _tname]];
	[_op] spawn VIOC_AA_fnc_runOp;
	"ok"
};

//=====================================================================================================================
// Gestor y consola
//=====================================================================================================================
VIOC_AA_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 60;
	VIOC_AA_AIRF = call VIOC_AA_fnc_airfields;
	VIOC_AA_NEXT = [time + ((VIOC_AA_EVERY max 5) * 60), time + ((VIOC_AA_EVERY max 5) * 60)];
	VIOC_AA_READY = true;
	[format ["activo: cada %1 min, escolta %2, Chinook %3, enemigo %4; aerodromos %5", VIOC_AA_EVERY, VIOC_AA_P_ESC, VIOC_AA_P_HEAVY, VIOC_AA_ENEMY,
		VIOC_AA_AIRF apply {(_x select 1) getVariable ["cti_town_name", "?"]}]] call VIOC_AA_fnc_log;
	if (VIOC_AA_EVERY <= 0) exitWith {["apagado (VIOC_AIR_ASSAULT = 0): solo VIOC_AA_fnc_force desde la consola"] call VIOC_AA_fnc_log};
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		sleep VIOC_AA_PERIOD;
		{
			private _side = _x;
			private _i = [_side] call VIOC_AA_fnc_idx;
			if (!(VIOC_AA_ACTIVE select _i) && {time >= (VIOC_AA_NEXT select _i)} && {[_side] call VIOC_AA_fnc_sideOn}) then {
				private _r = [_side] call VIOC_AA_fnc_plan;
				if !(_r isEqualTo "ok") then {
					VIOC_AA_NEXT set [_i, time + VIOC_AA_RETRY];
					VIOC_AA_LAST set [_i, format ["no salio: %1", _r]];
					[format ["%1: no salio (%2); otro intento en %3 s", _side, _r, VIOC_AA_RETRY]] call VIOC_AA_fnc_log;
				};
			};
		} forEach [west, east];
	};
};

//--- [bando, gratis (true), transporte, escolta] -> "ok" o el motivo (sin esperar el intervalo; nunca dos a la vez)
VIOC_AA_fnc_force = {
	params [["_side", west], ["_free", true], ["_want", ""], ["_wantEsc", -1]];
	if (!VIOC_AA_READY) exitWith {"todavia no esta listo (espera a que los pueblos tengan duenio + 1 min)"};
	private _r = [_side, _free, _want, _wantEsc] call VIOC_AA_fnc_plan;
	[format ["forzado %1: %2", _side, _r]] call VIOC_AA_fnc_log;
	_r
};

VIOC_AA_fnc_info = {
	private _lines = [format ["VIOC air_assault: cada %1 min (0 = no), escolta %2 por ciento, Chinook %3 por ciento, enemigo %4, listo %5 | INFO %6 (lanzados, desembarcos, derribados, tomados, cancelados, escoltas, Chinook)",
		VIOC_AA_EVERY, VIOC_AA_P_ESC, VIOC_AA_P_HEAVY, VIOC_AA_ENEMY, VIOC_AA_READY, VIOC_AA_INFO]];
	{
		private _side = _x;
		private _i = [_side] call VIOC_AA_fnc_idx;
		_lines pushBack format ["%1: automatico %2, en curso %3, proximo en %4 s, nivel aereo %5, salidas %6 | transporte %7, Chinook %8, escolta %9 | ultimo: %10",
			_side, [_side] call VIOC_AA_fnc_sideOn, VIOC_AA_ACTIVE select _i, round (((VIOC_AA_NEXT select _i) - time) max 0), [_side] call VIOC_AA_fnc_airLevel,
			([_side] call VIOC_AA_fnc_origins) apply {_x select 1}, [_side, "bh"] call VIOC_AA_fnc_pickAir, [_side, "ch"] call VIOC_AA_fnc_pickAir,
			[_side, "esc"] call VIOC_AA_fnc_pickAir, VIOC_AA_LAST select _i];
	} forEach [west, east];
	{
		private _team = _x get "team";
		_lines pushBack format ["#%1 %2 hacia %3: %4 desde hace %5 s, %6 (%7 hombres, %8 vivos), escolta %9 (viva %10)", _x get "id", _x get "side", _x get "tname",
			_x get "phase", round (time - (_x get "t0")), _x get "cls", _x get "n", if (isNull _team) then {0} else {{alive _x} count (units _team)},
			_x get "esc", alive (_x get "escV")];
	} forEach VIOC_AA_OPS;
	private _txt = _lines joinString (toString [10]);
	diag_log _txt;
	copyToClipboard _txt;
	_txt
};

[] spawn VIOC_AA_fnc_loop;

